const RblxUIStyleVarInfo* RblxUI::GetStyleVarInfo(RblxUIStyleVar idx)
{
    RBLXUI_ASSERT(idx >= 0 && idx < RblxUIStyleVar_COUNT);
    RBLXUI_STATIC_ASSERT(RBLXUI_COUNTOF(GStyleVarsInfo) == RblxUIStyleVar_COUNT);
    return &GStyleVarsInfo[idx];
}

void RblxUI::PushStyleVar(RblxUIStyleVar idx, float val)
{
    RblxUIContext& g = *GRblxUI;
    const RblxUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    RBLXUI_ASSERT_USER_ERROR_RET(var_info->DataType == RblxUIDataType_Float && var_info->Count == 1, "Calling PushStyleVar() variant with wrong type!");
    float* pvar = (float*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(RblxUIStyleMod(idx, *pvar));
    *pvar = val;
}

void RblxUI::PushStyleVarX(RblxUIStyleVar idx, float val_x)
{
    RblxUIContext& g = *GRblxUI;
    const RblxUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    RBLXUI_ASSERT_USER_ERROR_RET(var_info->DataType == RblxUIDataType_Float && var_info->Count == 2, "Calling PushStyleVar() variant with wrong type!");
    RblxVec2* pvar = (RblxVec2*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(RblxUIStyleMod(idx, *pvar));
    pvar->x = val_x;
}

void RblxUI::PushStyleVarY(RblxUIStyleVar idx, float val_y)
{
    RblxUIContext& g = *GRblxUI;
    const RblxUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    RBLXUI_ASSERT_USER_ERROR_RET(var_info->DataType == RblxUIDataType_Float && var_info->Count == 2, "Calling PushStyleVar() variant with wrong type!");
    RblxVec2* pvar = (RblxVec2*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(RblxUIStyleMod(idx, *pvar));
    pvar->y = val_y;
}

void RblxUI::PushStyleVar(RblxUIStyleVar idx, const RblxVec2& val)
{
    RblxUIContext& g = *GRblxUI;
    const RblxUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    RBLXUI_ASSERT_USER_ERROR_RET(var_info->DataType == RblxUIDataType_Float && var_info->Count == 2, "Calling PushStyleVar() variant with wrong type!");
    RblxVec2* pvar = (RblxVec2*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(RblxUIStyleMod(idx, *pvar));
    *pvar = val;
}

void RblxUI::PopStyleVar(int count)
{
    RblxUIContext& g = *GRblxUI;
    if (g.StyleVarStack.Size < count)
    {
        RBLXUI_ASSERT_USER_ERROR(0, "Calling PopStyleVar() too many times!");
        count = g.StyleVarStack.Size;
    }
    while (count > 0)
    {
        // We avoid a generic memcpy(data, &backup.Backup.., GDataTypeSize[info->Type] * info->Count), the overhead in Debug is not worth it.
        RblxUIStyleMod& backup = g.StyleVarStack.back();
        const RblxUIStyleVarInfo* var_info = GetStyleVarInfo(backup.VarIdx);
        void* data = var_info->GetVarPtr(&g.Style);
        if (var_info->DataType == RblxUIDataType_Float && var_info->Count == 1)      { ((float*)data)[0] = backup.BackupFloat[0]; }
        else if (var_info->DataType == RblxUIDataType_Float && var_info->Count == 2) { ((float*)data)[0] = backup.BackupFloat[0]; ((float*)data)[1] = backup.BackupFloat[1]; }
        g.StyleVarStack.pop_back();
        count--;
    }
}

