void RblxUI::SetNextWindowPos(const RblxVec2& pos, RblxUICond cond, const RblxVec2& pivot)
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT(cond == 0 || RblxIsPowerOfTwo(cond)); // Make sure the user doesn't attempt to combine multiple condition flags.
    g.NextWindowData.HasFlags |= RblxUINextWindowDataFlags_HasPos;
    g.NextWindowData.PosVal = pos;
    g.NextWindowData.PosPivotVal = pivot;
    g.NextWindowData.PosCond = cond ? cond : RblxUICond_Always;
    g.NextWindowData.PosUndock = true;
}

void RblxUI::SetNextWindowSize(const RblxVec2& size, RblxUICond cond)
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT(cond == 0 || RblxIsPowerOfTwo(cond)); // Make sure the user doesn't attempt to combine multiple condition flags.
    g.NextWindowData.HasFlags |= RblxUINextWindowDataFlags_HasSize;
    g.NextWindowData.SizeVal = size;
    g.NextWindowData.SizeCond = cond ? cond : RblxUICond_Always;
}

// For each axis:
// - Use 0.0f as min or FLT_MAX as max if you don't want limits, e.g. size_min = (500.0f, 0.0f), size_max = (FLT_MAX, FLT_MAX) sets a minimum width.
// - Use -1 for both min and max of same axis to preserve current size which itself is a constraint.
// - See "Demo->Examples->Constrained-resizing window" for examples.
void RblxUI::SetNextWindowSizeConstraints(const RblxVec2& size_min, const RblxVec2& size_max, RblxUISizeCallback custom_callback, void* custom_callback_user_data)
{
    RblxUIContext& g = *GRblxUI;
    g.NextWindowData.HasFlags |= RblxUINextWindowDataFlags_HasSizeConstraint;
    g.NextWindowData.SizeConstraintRect = RblxRect(size_min, size_max);
    g.NextWindowData.SizeCallback = custom_callback;
    g.NextWindowData.SizeCallbackUserData = custom_callback_user_data;
}

