void RblxUI::PushFocusScope(RblxUIID id)
{
    RblxUIContext& g = *GRblxUI;
    RblxUIFocusScopeData data;
    data.ID = id;
    data.WindowID = g.CurrentWindow->ID;
    g.FocusScopeStack.push_back(data);
    g.CurrentFocusScopeId = id;
}

void RblxUI::PopFocusScope()
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT_USER_ERROR_RET(g.FocusScopeStack.Size > g.StackSizesInBeginForCurrentWindow->SizeOfFocusScopeStack, "Calling PopFocusScope() too many times!");
    g.FocusScopeStack.pop_back();
    g.CurrentFocusScopeId = g.FocusScopeStack.Size ? g.FocusScopeStack.back().ID : 0;
}

bool RblxUI::IsInNavFocusRoute(RblxUIID focus_scope_id)
{
    RblxUIContext& g = *GRblxUI;
    if (g.NavFocusScopeId == focus_scope_id)
        return true;
    for (const RblxUIFocusScopeData& focus_scope : g.NavFocusRoute)
        if (focus_scope.ID == focus_scope_id)
            return true;
    return false;
}

void RblxUI::SetNavFocusScope(RblxUIID focus_scope_id)
{
    RblxUIContext& g = *GRblxUI;
    g.NavFocusScopeId = focus_scope_id;
    g.NavFocusRoute.resize(0); // Invalidate
    if (focus_scope_id == 0)
        return;
    RBLXUI_ASSERT(g.NavWindow != NULL);

    // Store current path (in reverse order)
    if (focus_scope_id == g.CurrentFocusScopeId)
    {
        // Top of focus stack contains local focus scopes inside current window
        for (int n = g.FocusScopeStack.Size - 1; n >= 0 && g.FocusScopeStack.Data[n].WindowID == g.CurrentWindow->ID; n--)
            g.NavFocusRoute.push_back(g.FocusScopeStack.Data[n]);
    }
    else if (focus_scope_id == g.NavWindow->NavRootFocusScopeId)
        g.NavFocusRoute.push_back({ focus_scope_id, g.NavWindow->ID });
    else
        return;

    // Then follow on manually set ParentWindowForFocusRoute field (#6798)
    for (RblxUIWindow* window = g.NavWindow->ParentWindowForFocusRoute; window != NULL; window = window->ParentWindowForFocusRoute)
        g.NavFocusRoute.push_back({ window->NavRootFocusScopeId, window->ID });
    RBLXUI_ASSERT(g.NavFocusRoute.Size < 100); // Maximum depth is technically 251 as per CalcRoutingScore(): 254 - 3
}

// Focus = move navigation cursor, set scrolling, set focus window.
void RblxUI::FocusItem()
{
    RblxUIContext& g = *GRblxUI;
    RblxUIWindow* window = g.CurrentWindow;
    RBLXUI_DEBUG_LOG_FOCUS("FocusItem(0x%08x) in window \"%s\"\n", g.LastItemData.ID, window->Name);
    if (g.DragDropActive || g.MovingWindow != NULL) // FIXME: Opt-in flags for this?
    {
        RBLXUI_DEBUG_LOG_FOCUS("FocusItem() ignored while DragDropActive!\n");
        return;
    }

    RblxUINavMoveFlags move_flags = RblxUINavMoveFlags_IsTabbing | RblxUINavMoveFlags_FocusApi | RblxUINavMoveFlags_NoSetNavCursorVisible | RblxUINavMoveFlags_NoSelect;
    RblxUIScrollFlags scroll_flags = window->Appearing ? RblxUIScrollFlags_KeepVisibleEdgeX | RblxUIScrollFlags_AlwaysCenterY : RblxUIScrollFlags_KeepVisibleEdgeX | RblxUIScrollFlags_KeepVisibleEdgeY;
    SetNavWindow(window);
    NavMoveRequestSubmit(RblxUIDir_None, RblxUIDir_Up, move_flags, scroll_flags);
    NavMoveRequestResolveWithLastItem(&g.NavMoveResultLocal);
}

void RblxUI::ActivateItemByID(RblxUIID id)
{
    RblxUIContext& g = *GRblxUI;
    g.NavNextActivateId = id;
    g.NavNextActivateFlags = RblxUIActivateFlags_None;
}

// Note: this will likely be called ActivateItem() once we rework our Focus/Activation system!
// But ActivateItem() should function without altering scroll/focus?
void RblxUI::SetKeyboardFocusHere(int offset)
{
    RblxUIContext& g = *GRblxUI;
    RblxUIWindow* window = g.CurrentWindow;
    RBLXUI_ASSERT(offset >= -1);    // -1 is allowed but not below
    RBLXUI_DEBUG_LOG_FOCUS("SetKeyboardFocusHere(%d) in window \"%s\"\n", offset, window->Name);

    // It makes sense in the vast majority of cases to never interrupt a drag and drop.
    // When we refactor this function into ActivateItem() we may want to make this an option.
    // MovingWindow is protected from most user inputs using SetActiveIdUsingNavAndKeys(), but
    // is also automatically dropped in the event g.ActiveId is stolen.
    if (g.DragDropActive || g.MovingWindow != NULL)
    {
        RBLXUI_DEBUG_LOG_FOCUS("SetKeyboardFocusHere() ignored while DragDropActive!\n");
        return;
    }

    SetNavWindow(window);

    RblxUINavMoveFlags move_flags = RblxUINavMoveFlags_IsTabbing | RblxUINavMoveFlags_Activate | RblxUINavMoveFlags_FocusApi | RblxUINavMoveFlags_NoSetNavCursorVisible;
    RblxUIScrollFlags scroll_flags = window->Appearing ? RblxUIScrollFlags_KeepVisibleEdgeX | RblxUIScrollFlags_AlwaysCenterY : RblxUIScrollFlags_KeepVisibleEdgeX | RblxUIScrollFlags_KeepVisibleEdgeY;
    NavMoveRequestSubmit(RblxUIDir_None, offset < 0 ? RblxUIDir_Up : RblxUIDir_Down, move_flags, scroll_flags); // FIXME-NAV: Once we refactor tabbing, add LegacyApi flag to not activate non-inputable.
    if (offset == -1)
    {
        NavMoveRequestResolveWithLastItem(&g.NavMoveResultLocal);
    }
    else
    {
        g.NavTabbingDir = 1;
        g.NavTabbingCounter = offset + 1;
    }
}

void RblxUI::SetItemDefaultFocus()
{
    RblxUIContext& g = *GRblxUI;
    RblxUIWindow* window = g.CurrentWindow;
    if (!window->Appearing)
        return;
    if (g.NavWindow != window->RootWindowForNav || (!g.NavInitRequest && g.NavInitResult.ID == 0) || g.NavLayer != window->DC.NavLayerCurrent)
        return;

    g.NavInitRequest = false;
    NavApplyItemToResult(&g.NavInitResult);
    NavUpdateAnyRequestFlag();

    // Scroll could be done in NavInitRequestApplyResult() via an opt-in flag (we however don't want regular init requests to scroll)
    if (!window->ClipRect.Contains(g.LastItemData.Rect))
        ScrollToRectEx(window, g.LastItemData.Rect, RblxUIScrollFlags_None);
}

