//-----------------------------------------------------------------------------
// [SECTION] FONTS, TEXTURES
//-----------------------------------------------------------------------------
// Most of the relevant font logic is in rblxui_draw.cpp.
// Those are high-level support functions.
//-----------------------------------------------------------------------------
// - UpdateTexturesNewFrame() [Internal]
// - UpdateTexturesEndFrame() [Internal]
// - UpdateFontsNewFrame() [Internal]
// - UpdateFontsEndFrame() [Internal]
// - GetDefaultFont() [Internal]
// - RegisterUserTexture() [Internal]
// - UnregisterUserTexture() [Internal]
// - RegisterFontAtlas() [Internal]
// - UnregisterFontAtlas() [Internal]
// - SetCurrentFont() [Internal]
// - UpdateCurrentFontSize() [Internal]
// - SetFontRasterizerDensity() [Internal]
// - PushFont()
// - PopFont()
//-----------------------------------------------------------------------------

static void RblxUI::UpdateTexturesNewFrame()
{
    // Cannot update every atlases based on atlas's FrameCount < g.FrameCount, because an atlas may be shared by multiple contexts with different frame count.
    RblxUIContext& g = *GRblxUI;
    const bool has_textures = (g.IO.BackendFlags & RblxUIBackendFlags_RendererHasTextures) != 0;
    for (RblxFontAtlas* atlas : g.FontAtlases)
    {
        if (atlas->OwnerContext == &g)
        {
            RblxFontAtlasUpdateNewFrame(atlas, g.FrameCount, has_textures);
        }
        else
        {
            // (1) If you manage font atlases yourself, e.g. create a RblxFontAtlas yourself you need to call RblxFontAtlasUpdateNewFrame() on it.
            // Otherwise, calling RblxUI::CreateContext() without parameter will create an atlas owned by the context.
            // (2) If you have multiple font atlases, make sure the 'atlas->RendererHasTextures' as specified in the RblxFontAtlasUpdateNewFrame() call matches for that.
            // (3) If you have multiple rblxui contexts, they also need to have a matching value for RblxUIBackendFlags_RendererHasTextures.
            RBLXUI_ASSERT(atlas->Builder != NULL && atlas->Builder->FrameCount != -1);
            RBLXUI_ASSERT(atlas->RendererHasTextures == has_textures);
        }
    }
    for (RblxTextureData* tex : g.UserTextures)
        RblxTextureDataUpdateNewFrame(tex);
}

// Build a single texture list
static void RblxUI::UpdateTexturesEndFrame()
{
    RblxUIContext& g = *GRblxUI;
    g.PlatformIO.Textures.resize(0);
    for (RblxFontAtlas* atlas : g.FontAtlases)
        for (RblxTextureData* tex : atlas->TexList)
        {
            // We provide this information so backends can decide whether to destroy textures.
            // This means in practice that if N rblxui contexts are created with a shared atlas, we assume all of them have a backend initialized.
            tex->RefCount = (unsigned short)atlas->RefCount;
            g.PlatformIO.Textures.push_back(tex);
        }
    for (RblxTextureData* tex : g.UserTextures)
        g.PlatformIO.Textures.push_back(tex);
}

void RblxUI::UpdateFontsNewFrame()
{
    RblxUIContext& g = *GRblxUI;
    if ((g.IO.BackendFlags & RblxUIBackendFlags_RendererHasTextures) == 0)
        for (RblxFontAtlas* atlas : g.FontAtlases)
            atlas->Locked = true;

    if (g.Style._NextFrameFontSizeBase != 0.0f)
    {
        g.Style.FontSizeBase = g.Style._NextFrameFontSizeBase;
        g.Style._NextFrameFontSizeBase = 0.0f;
    }

    // Apply default font size the first time
    RblxFont* font = RblxUI::GetDefaultFont();
    if (g.Style.FontSizeBase <= 0.0f)
        g.Style.FontSizeBase = (font->LegacySize > 0.0f ? font->LegacySize : FONT_DEFAULT_SIZE_BASE);

    // Set initial font
    g.Font = font;
    g.FontSizeBase = g.Style.FontSizeBase;
    g.FontSize = 0.0f;
    RblxFontStackData font_stack_data = { font, g.Style.FontSizeBase, g.Style.FontSizeBase };           // <--- Will restore FontSize
    SetCurrentFont(font_stack_data.Font, font_stack_data.FontSizeBeforeScaling, 0.0f); // <--- but use 0.0f to enable scale
    g.FontStack.push_back(font_stack_data);
    RBLXUI_ASSERT(g.Font->IsLoaded());
}

void RblxUI::UpdateFontsEndFrame()
{
    PopFont();
}

RblxFont* RblxUI::GetDefaultFont()
{
    RblxUIContext& g = *GRblxUI;
    RblxFontAtlas* atlas = g.IO.Fonts;
    if (atlas->Builder == NULL || atlas->Fonts.Size == 0)
        RblxFontAtlasBuildMain(atlas);
    return g.IO.FontDefault ? g.IO.FontDefault : atlas->Fonts[0];
}

// EXPERIMENTAL. Use RblxTextureDataQueueUpload() to queue updates. Textures logic will be automatically be updated in NewFrame().
void RblxUI::RegisterUserTexture(RblxTextureData* tex)
{
    RblxUIContext& g = *GRblxUI;
    tex->RefCount++;
    g.UserTextures.push_back(tex);
}

void RblxUI::UnregisterUserTexture(RblxTextureData* tex)
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT(tex->RefCount > 0);
    tex->RefCount--;
    g.UserTextures.find_erase(tex);
}

void RblxUI::RegisterFontAtlas(RblxFontAtlas* atlas)
{
    RblxUIContext& g = *GRblxUI;
    if (g.FontAtlases.Size == 0)
        RBLXUI_ASSERT(atlas == g.IO.Fonts);
    atlas->RefCount++;
    g.FontAtlases.push_back(atlas);
    RblxFontAtlasAddDrawListSharedData(atlas, &g.DrawListSharedData);
    for (RblxTextureData* tex : atlas->TexList)
        tex->RefCount = (unsigned short)atlas->RefCount;
}

void RblxUI::UnregisterFontAtlas(RblxFontAtlas* atlas)
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT(atlas->RefCount > 0);
    RblxFontAtlasRemoveDrawListSharedData(atlas, &g.DrawListSharedData);
    g.FontAtlases.find_erase(atlas);
    atlas->RefCount--;
    for (RblxTextureData* tex : atlas->TexList)
        tex->RefCount = (unsigned short)atlas->RefCount;
}

// Use RblxDrawList::_SetTexture(), making our shared g.FontStack[] authoritative against window-local RblxDrawList.
// - Whereas RblxDrawList::PushTexture()/PopTexture() is not to be used across Begin() calls.
// - Note that we don't propagate current texture id when e.g. Begin()-ing into a new window, we never really did...
//   - Some code paths never really fully worked with multiple atlas textures.
//   - The right-ish solution may be to remove _SetTexture() and make AddText/RenderText lazily call PushTexture()/PopTexture()
//     the same way AddImage() does, but then all other primitives would also need to? I don't think we should tackle this problem
//     because we have a concrete need and a test bed for multiple atlas textures.
// FIXME-NEWATLAS-V2: perhaps we can now leverage RblxFontAtlasUpdateDrawListsTextures() ?
void RblxUI::SetCurrentFont(RblxFont* font, float font_size_before_scaling, float font_size_after_scaling)
{
    RblxUIContext& g = *GRblxUI;
    g.Font = font;
    g.FontSizeBase = font_size_before_scaling;
    UpdateCurrentFontSize(font_size_after_scaling);

    if (font != NULL)
    {
        RBLXUI_ASSERT(font && font->IsLoaded());    // Font Atlas not created. Did you call io.Fonts->GetTexDataAsRGBA32 / GetTexDataAsAlpha8 ?
#ifndef RBLXUI_DISABLE_OBSOLETE_FUNCTIONS
        RBLXUI_ASSERT(font->Scale > 0.0f);
#endif
        RblxFontAtlas* atlas = font->OwnerAtlas;
        g.DrawListSharedData.FontAtlas = atlas;
        g.DrawListSharedData.Font = font;
        RblxFontAtlasUpdateDrawListsSharedData(atlas);
        if (g.CurrentWindow != NULL)
            g.CurrentWindow->DrawList->_SetTexture(atlas->TexRef);
    }
}

void RblxUI::UpdateCurrentFontSize(float restore_font_size_after_scaling)
{
    RblxUIContext& g = *GRblxUI;
    RblxUIWindow* window = g.CurrentWindow;

    g.Style.FontSizeBase = g.FontSizeBase;

    // Restoring is pretty much only used by PopFont()
    float final_size = (restore_font_size_after_scaling > 0.0f) ? restore_font_size_after_scaling : 0.0f;
    if (final_size == 0.0f)
    {
        final_size = g.FontSizeBase;

        // Global scale factors
        final_size *= g.Style.FontScaleMain;    // Main global scale factor
        final_size *= g.Style.FontScaleDpi;     // Per-monitor/viewport DPI scale factor (in docking branch: automatically updated when io.ConfigDpiScaleFonts is enabled).

        // Window scale (mostly obsolete now)
        if (window != NULL)
            final_size *= window->FontWindowScale;

        // Legacy scale factors
#ifndef RBLXUI_DISABLE_OBSOLETE_FUNCTIONS
        final_size *= g.IO.FontGlobalScale; // Use style.FontScaleMain instead!
        if (g.Font != NULL)
            final_size *= g.Font->Scale;    // Was never really useful.
#endif
    }

    // Round font size
    // - We started rounding in 1.90 WIP (18991) as our layout system currently doesn't support non-rounded font size well yet.
    // - We may support it better later and remove this rounding.
    final_size = GetRoundedFontSize(final_size);
    final_size = RblxClamp(final_size, 1.0f, RBLXUI_FONT_SIZE_MAX);
    if (g.Font != NULL && (g.IO.BackendFlags & RblxUIBackendFlags_RendererHasTextures))
        g.Font->CurrentRasterizerDensity = g.FontRasterizerDensity;

    g.FontSize = final_size;
    g.DrawListSharedData.FontSize = g.FontSize;

    // Early out to avoid hidden window keeping bakes referenced and out of GC reach.
    // - However this leave a pretty subtle and damning error surface area if g.FontBaked was mismatching.
    //   Probably needs to be reevaluated into e.g. setting g.FontBaked = nullptr to mark it as dirty.
    // - Note that 'PushFont(); Begin(); End(); PopFont()' from within any collapsed window is not compromised, because Begin() calls SetCurrentWindow()->...->UpdateCurrentSize()
    if (window != NULL && window->SkipItems)
    {
        RblxUITable* table = g.CurrentTable;
        const bool allow_early_out = table == NULL || (table->CurrentColumn != -1 && table->Columns[table->CurrentColumn].IsSkipItems == false); // See 8465#issuecomment-2951509561 and #8865. Ideally the SkipItems=true in tables would be amended with extra data.
        if (allow_early_out)
            return;
    }

    g.FontBaked = (g.Font != NULL && window != NULL) ? g.Font->GetFontBaked(final_size) : NULL;
    g.FontBakedScale = (g.FontBaked != NULL) ? (g.FontSize / g.FontBaked->Size) : 0.0f;
    g.DrawListSharedData.FontScale = g.FontBakedScale;
}

// Exposed in case user may want to override setting density.
// IMPORTANT: Begin()/End() is overriding density. Be considerate of this you change it.
void RblxUI::SetFontRasterizerDensity(float rasterizer_density)
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT(g.IO.BackendFlags & RblxUIBackendFlags_RendererHasTextures);
    if (g.FontRasterizerDensity == rasterizer_density)
        return;
    g.FontRasterizerDensity = rasterizer_density;
    UpdateCurrentFontSize(0.0f);
}

// If you want to scale an existing font size! Read comments in rblxui.h!
void RblxUI::PushFont(RblxFont* font, float font_size_base)
{
    RblxUIContext& g = *GRblxUI;
    if (font == NULL) // Before 1.92 (June 2025), PushFont(NULL) == PushFont(GetDefaultFont())
        font = g.Font;
    RBLXUI_ASSERT(font != NULL);
    RBLXUI_ASSERT(font_size_base >= 0.0f);

    g.FontStack.push_back({ g.Font, g.FontSizeBase, g.FontSize });
    if (font_size_base == 0.0f)
        font_size_base = g.FontSizeBase; // Keep current font size
    SetCurrentFont(font, font_size_base, 0.0f);
}

void  RblxUI::PopFont()
{
    RblxUIContext& g = *GRblxUI;
    RBLXUI_ASSERT_USER_ERROR_RET(g.FontStack.Size > 0, "Calling PopFont() too many times!");
    RblxFontStackData* font_stack_data = &g.FontStack.back();
    SetCurrentFont(font_stack_data->Font, font_stack_data->FontSizeBeforeScaling, font_stack_data->FontSizeAfterScaling);
    g.FontStack.pop_back();
}

