// Push a given id value ignoring the ID stack as a seed.
void RblxUI::PushOverrideID(RblxUIID id)
{
    RblxUIContext& g = *GRblxUI;
    RblxUIWindow* window = g.CurrentWindow;
#ifndef RBLXUI_DISABLE_DEBUG_TOOLS
    if (g.DebugHookIdInfoId == id)
        DebugHookIdInfo(id, RblxUIDataType_ID, NULL, NULL);
#endif
    window->IDStack.push_back(id);
}

// Helper to avoid a common series of PushOverrideID -> GetID() -> PopID() call
// (note that when using this pattern, ID Stack Tool will tend to not display the intermediate stack level.
//  for that to work we would need to do PushOverrideID() -> ItemAdd() -> PopID() which would alter widget code a little more)
RblxUIID RblxUI::GetIDWithSeed(const char* str, const char* str_end, RblxUIID seed)
{
    RblxUIID id = RblxHashStr(str, str_end ? (str_end - str) : 0, seed);
#ifndef RBLXUI_DISABLE_DEBUG_TOOLS
    RblxUIContext& g = *GRblxUI;
    if (g.DebugHookIdInfoId == id)
        DebugHookIdInfo(id, RblxUIDataType_String, str, str_end);
#endif
    return id;
}

RblxUIID RblxUI::GetIDWithSeed(int n, RblxUIID seed)
{
    RblxUIID id = RblxHashData(&n, sizeof(n), seed);
#ifndef RBLXUI_DISABLE_DEBUG_TOOLS
    RblxUIContext& g = *GRblxUI;
    if (g.DebugHookIdInfoId == id)
        DebugHookIdInfo(id, RblxUIDataType_S32, (void*)(intptr_t)n, NULL);
#endif
    return id;
}

void RblxUI::PopID()
{
    RblxUIWindow* window = GRblxUI->CurrentWindow;
    RBLXUI_ASSERT_USER_ERROR_RET(window->IDStack.Size > 1, "Calling PopID() too many times!");
    window->IDStack.pop_back();
}

