static RblxUIKeyChord GetModForLRModKey(RblxUIKey key)
{
    if (key == RblxUIKey_LeftCtrl || key == RblxUIKey_RightCtrl)
        return RblxUIMod_Ctrl;
    if (key == RblxUIKey_LeftShift || key == RblxUIKey_RightShift)
        return RblxUIMod_Shift;
    if (key == RblxUIKey_LeftAlt || key == RblxUIKey_RightAlt)
        return RblxUIMod_Alt;
    if (key == RblxUIKey_LeftSuper || key == RblxUIKey_RightSuper)
        return RblxUIMod_Super;
    return RblxUIMod_None;
}

RblxUIKeyChord RblxUI::FixupKeyChord(RblxUIKeyChord key_chord)
{
    // Add RblxUIMod_XXXX when a corresponding RblxUIKey_LeftXXX/RblxUIKey_RightXXX is specified.
    RblxUIKey key = (RblxUIKey)(key_chord & ~RblxUIMod_Mask_);
    if (IsLRModKey(key))
        key_chord |= GetModForLRModKey(key);
    return key_chord;
}

RblxUIKeyData* RblxUI::GetKeyData(RblxUIContext* ctx, RblxUIKey key)
{
    RblxUIContext& g = *ctx;

    // Special storage location for mods
    if (key & RblxUIMod_Mask_)
        key = ConvertSingleModFlagToKey(key);

    RBLXUI_ASSERT(IsNamedKey(key) && "Support for user key indices was dropped in favor of RblxUIKey. Please update backend & user code.");
    return &g.IO.KeysData[key - RblxUIKey_NamedKey_BEGIN];
}

