void RblxUI::LocalizeRegisterEntries(const RblxUILocEntry* entries, int count)
{
    RblxUIContext& g = *GRblxUI;
    for (int n = 0; n < count; n++)
        g.LocalizationTable[entries[n].Key] = entries[n].Text;
}

